BEGIN;

INSERT INTO public.equipment_items (id, name, category, subcategory, data)
SELECT id, name, 'magic', subcategory,
  jsonb_build_object(
    'id', id,
    'name', name,
    'category', 'magic',
    'subcategory', subcategory,
    'rarity', rarity,
    'attunement', attunement,
    'priceCp', NULL,
    'weightKg', NULL,
    'unit', 'unidade',
    'description', description,
    'properties', ARRAY[]::text[],
    'sourcePage', NULL,
    'aliases', ARRAY[]::text[]
  )
FROM (VALUES
  ('faixas-de-ferro-de-bilarro', 'Faixas de Ferro de Bilarro', 'Itens maravilhosos', 'raro', NULL, 'Esfera de ferro que pode ser arremessada contra criatura Enorme ou menor a até 18 m. Ao acertar, as faixas a deixam impedida até serem libertadas por comando ou teste de Força CD 20; se as faixas forem partidas, o item é destruído. Recarrega ao amanhecer.'),
  ('ferraduras-da-velocidade', 'Ferraduras da Velocidade', 'Itens maravilhosos', 'raro', NULL, 'Conjunto de quatro ferraduras que, fixadas aos cascos de cavalo ou criatura similar, aumenta seu deslocamento de caminhada em 9 m.'),
  ('ferraduras-do-zefiro', 'Ferraduras do Zéfiro', 'Itens maravilhosos', 'muito raro', NULL, 'Conjunto de quatro ferraduras que permite à criatura flutuar a 10 cm do solo, cruzar superfícies não sólidas ou instáveis, não deixar rastros e ignorar terreno difícil. Também permite marchar por até 1 hora por dia sem exaustão.'),
  ('filtro-do-amor', 'Filtro do Amor', 'Poções', 'incomum', NULL, 'A próxima criatura que você vir em até 10 minutos após beber fica enfeitiçada por você durante 1 hora. Se corresponder às suas preferências, você a reconhece como seu amor verdadeiro enquanto durar o efeito.'),
  ('flauta-assombrada', 'Flauta Assombrada', 'Instrumentos', 'incomum', NULL, 'Requer proficiência com instrumentos de sopro. Tem 3 cargas; ao tocar, pode gastar 1 para que criaturas escolhidas a até 9 m que ouçam façam resistência de Sabedoria CD 15 ou fiquem amedrontadas por 1 minuto. Recupera 1d3 cargas ao amanhecer.'),
  ('flauta-dos-esgotos', 'Flauta dos Esgotos', 'Instrumentos', 'incomum', 'sim', 'Requer proficiência com instrumentos de sopro. Enquanto sintonizado, ratos não o atacam sem provocação. Tem 3 cargas para atrair enxames de ratos próximos; ao tocar, pode tentar tornar amigável e controlar um enxame com um teste resistido de Carisma. Recupera 1d3 cargas ao amanhecer.'),
  ('flecha-assassina', 'Flecha Assassina', 'Munições mágicas', 'muito raro', NULL, 'Munição mágica feita para um tipo, raça ou grupo específico de criatura. Ao sofrer dano dela, o alvo faz resistência de Constituição CD 17 ou sofre 6d10 de dano adicional, metade se passar. Depois, a flecha torna-se não mágica.'),
  ('fortaleza-instantanea-de-daern', 'Fortaleza Instantânea de Daern', 'Itens maravilhosos', 'raro', NULL, 'Cubo metálico que se transforma por comando em uma torre de adamante de dois pisos. Criaturas na área sofrem 10d10 de dano de concussão e são empurradas para fora (Destreza CD 15 reduz o dano à metade). A fortaleza tem paredes, porta e cobertura resistentes; só pode ser recolhida vazia.'),
  ('frasco-de-ferro', 'Frasco de Ferro', 'Itens maravilhosos', 'lendário', NULL, 'Garrafa capaz de aprisionar uma criatura extraplanar visível a até 18 m que falhe em resistência de Sabedoria CD 17. Contém uma criatura, que não envelhece nem precisa respirar, comer ou beber. Libertada por comando, serve amigavelmente por 1 hora; o conteúdo inicial pode ser determinado aleatoriamente.'),
  ('garrafa-de-fumaca-eterna', 'Garrafa de Fumaça Eterna', 'Itens maravilhosos', 'incomum', NULL, 'Ao abrir, enche a área com fumaça de escuridão densa em raio inicial de 18 m, que cresce até 36 m. A fumaça persiste enquanto aberta e se dispersa após fechada; ventos também a dissipam.'),
  ('garrafa-do-efreeti', 'Garrafa do Efreeti', 'Itens maravilhosos', 'muito raro', NULL, 'Ao abrir, pode libertar um efreeti hostil, fazê-lo servir por uma hora em até três aberturas, ou permitir que conceda três desejos; o resultado é determinado na primeira abertura. Depois do efeito final, perde a magia.'),
  ('gema-da-luminosidade', 'Gema da Luminosidade', 'Itens maravilhosos', 'incomum', NULL, 'Prisma com 50 cargas. Emite luz à vontade; também pode gastar cargas para disparar um raio ou cone de luz cegante (Constituição CD 15). Ao esgotar as cargas, torna-se joia não mágica de 50 po; esse valor não é preço de compra.'),
  ('gema-de-visao', 'Gema de Visão', 'Itens maravilhosos', 'raro', 'sim', 'Tem 3 cargas. Uma carga concede visão verdadeira até 36 m por 10 minutos. Recupera 1d3 cargas ao amanhecer.'),
  ('gema-elemental', 'Gema Elemental', 'Itens maravilhosos', 'incomum', NULL, 'Gema com centelha elemental que, ao ser quebrada, invoca um elemental conforme sua cor (ar, terra, fogo ou água), como conjurar elemental; a gema é consumida.'),
  ('globo-de-fluxo', 'Globo de Fluxo', 'Itens maravilhosos', 'incomum', NULL, 'Esfera que, por comando a até 18 m, emana luz ou luz do dia (esta última recarrega ao amanhecer). Também pode flutuar e seguir seu portador, apagando-se se não puder acompanhá-lo.'),
  ('instrumento-dos-bardos-harpa-de-anstruth', 'Harpa de Anstruth', 'Instrumentos', 'muito raro', 'bardo', 'Instrumento dos Bardos. Exige sintonização por um bardo; criatura não sintonizada que tente tocar faz resistência de Sabedoria CD 15 ou sofre 2d4 de dano psíquico. Permite conjurar voo, invisibilidade, levitação, proteção contra o bem e mal, controlar o clima, curar ferimentos (5º nível) e muralha de espinhos; cada magia só pode ser conjurada uma vez até o amanhecer. Alvos têm desvantagem nas resistências contra magias de encantamento conjuradas pelo instrumento.'),
  ('instrumento-dos-bardos-mandolim-de-canaith', 'Bandolim de Canaith', 'Instrumentos', 'raro', 'bardo', 'Instrumento dos Bardos. Exige sintonização por um bardo; criatura não sintonizada que tente tocar faz resistência de Sabedoria CD 15 ou sofre 2d4 de dano psíquico. Permite conjurar voo, invisibilidade, levitação, proteção contra o bem e mal, curar ferimentos (3º nível), dissipar magia e proteção contra energia (apenas elétrico); cada magia só pode ser conjurada uma vez até o amanhecer. Alvos têm desvantagem nas resistências contra magias de encantamento conjuradas pelo instrumento.'),
  ('instrumento-dos-bardos-lira-de-cli', 'Lira de Cli', 'Instrumentos', 'raro', 'bardo', 'Instrumento dos Bardos. Exige sintonização por um bardo; criatura não sintonizada que tente tocar faz resistência de Sabedoria CD 15 ou sofre 2d4 de dano psíquico. Permite conjurar voo, invisibilidade, levitação, proteção contra o bem e mal, moldar rochas, muralha de fogo e muralha de vento; cada magia só pode ser conjurada uma vez até o amanhecer. Alvos têm desvantagem nas resistências contra magias de encantamento conjuradas pelo instrumento.'),
  ('instrumento-dos-bardos-alaude-de-doss', 'Alaúde de Doss', 'Instrumentos', 'incomum', 'bardo', 'Instrumento dos Bardos. Exige sintonização por um bardo; criatura não sintonizada que tente tocar faz resistência de Sabedoria CD 15 ou sofre 2d4 de dano psíquico. Permite conjurar voo, invisibilidade, levitação, proteção contra o bem e mal, amizade animal, proteção contra energia (apenas fogo) e proteção contra veneno; cada magia só pode ser conjurada uma vez até o amanhecer. Alvos têm desvantagem nas resistências contra magias de encantamento conjuradas pelo instrumento.'),
  ('instrumento-dos-bardos-bandolim-de-fochlucan', 'Bandolim de Fochlucan', 'Instrumentos', 'incomum', 'bardo', 'Instrumento dos Bardos. Exige sintonização por um bardo; criatura não sintonizada que tente tocar faz resistência de Sabedoria CD 15 ou sofre 2d4 de dano psíquico. Permite conjurar voo, invisibilidade, levitação, proteção contra o bem e mal, constrição, fogo das fadas, bordão místico e falar com animais; cada magia só pode ser conjurada uma vez até o amanhecer. Alvos têm desvantagem nas resistências contra magias de encantamento conjuradas pelo instrumento.'),
  ('instrumento-dos-bardos-citara-de-mac-fuirmidh', 'Cítara de Mac-Fuirmidh', 'Instrumentos', 'incomum', 'bardo', 'Instrumento dos Bardos. Exige sintonização por um bardo; criatura não sintonizada que tente tocar faz resistência de Sabedoria CD 15 ou sofre 2d4 de dano psíquico. Permite conjurar voo, invisibilidade, levitação, proteção contra o bem e mal, pele de árvore, curar ferimentos e névoa obscurecente; cada magia só pode ser conjurada uma vez até o amanhecer. Alvos têm desvantagem nas resistências contra magias de encantamento conjuradas pelo instrumento.'),
  ('instrumento-dos-bardos-harpa-de-ollamh', 'Harpa de Ollamh', 'Instrumentos', 'lendário', 'bardo', 'Instrumento dos Bardos. Exige sintonização por um bardo; criatura não sintonizada que tente tocar faz resistência de Sabedoria CD 15 ou sofre 2d4 de dano psíquico. Permite conjurar voo, invisibilidade, levitação, proteção contra o bem e mal, confusão, controlar o clima e tempestade de fogo; cada magia só pode ser conjurada uma vez até o amanhecer. Alvos têm desvantagem nas resistências contra magias de encantamento conjuradas pelo instrumento.'),
  ('jarro-de-alquimia', 'Jarro de Alquimia', 'Itens maravilhosos', 'incomum', NULL, 'Jarro que produz, por comando, líquidos escolhidos de uma lista, como ácido, óleo, veneno, cerveja, mel, água, vinagre e vinho, em quantidades limitadas. Só pode produzir um tipo por dia.'),
  ('ladra-das-nove-vidas', 'Ladra das Nove Vidas', 'Armas mágicas', 'muito raro', 'sim', 'Espada mágica +2 com 1d8 + 1 cargas. Em um acerto crítico contra criatura com até 100 PV, o alvo faz resistência de Constituição CD 15 ou morre instantaneamente; constructos e mortos-vivos são imunes. Cada morte consome uma carga; sem cargas, perde essa propriedade.'),
  ('lamina-da-sorte', 'Lâmina da Sorte', 'Armas mágicas', 'lendário', 'sim', 'Espada mágica +1 que também concede +1 em testes de resistência. Uma vez por dia, permite repetir uma jogada de ataque, teste de habilidade ou resistência. Possui 1d4 − 1 cargas para conjurar desejo; essa propriedade desaparece quando as cargas acabam.'),
  ('lamina-do-sol', 'Lâmina do Sol', 'Armas mágicas', 'raro', 'sim', 'Cabo que projeta uma lâmina de radiação pura, uma espada longa mágica acuidade +2 que causa dano radiante e 1d8 adicional contra mortos-vivos. Emite luz, cujo alcance pode ser ajustado.'),
  ('lanterna-de-revelacao', 'Lanterna de Revelação', 'Itens maravilhosos', 'incomum', NULL, 'Lanterna que, acesa com óleo, ilumina 9 m com luz plena e mais 9 m com penumbra por até 6 horas. Criaturas e objetos invisíveis ficam visíveis na luz plena; o capuz reduz a iluminação.'),
  ('leque-do-vento', 'Leque do Vento', 'Itens maravilhosos', 'incomum', NULL, 'Permite conjurar lufada de vento (CD 13). Após o primeiro uso do dia, cada uso adicional tem 20% cumulativo de falhar e destruir o leque.'),
  ('lingua-flamejante', 'Língua Flamejante', 'Armas mágicas', 'raro', 'sim', 'Espada que, por palavra de comando, fica em chamas, ilumina 12 m e causa 2d6 de dano de fogo adicional. As chamas terminam por comando, ao largar ou embainhar a arma.'),
  ('luvas-de-apanhar-projeteis', 'Luvas de Apanhar Projéteis', 'Itens maravilhosos', 'incomum', 'sim', 'Com uma mão livre, pode usar reação para reduzir em 1d10 + modificador de Destreza o dano de um ataque armado à distância; se reduzir a zero, pode apanhar o projétil se couber na mão.'),
  ('luvas-de-destreza', 'Luvas de Destreza', 'Itens maravilhosos', 'raro', 'sim', 'Define Destreza como 19 enquanto usadas; não têm efeito se o valor já for 19 ou maior.'),
  ('luvas-de-nadar-e-escalar', 'Luvas de Nadar e Escalar', 'Itens maravilhosos', 'incomum', 'sim', 'Nadar e escalar não custam movimento adicional e as luvas concedem +5 em testes de Força (Atletismo) para nadar ou escalar.'),
  ('luvas-do-ladrao', 'Luvas do Ladrão', 'Itens maravilhosos', 'incomum', NULL, 'Ficam invisíveis quando vestidas e concedem +5 em testes de Destreza (Prestidigitação) e para abrir fechaduras.'),
  ('maca-da-destruicao', 'Maça da Destruição', 'Armas mágicas', 'raro', NULL, 'Maça mágica +1, ou +3 contra constructos. Um 20 no ataque causa 7 de dano de concussão adicional (14 contra constructos); constructo com até 25 PV após esse dano é destruído.'),
  ('maca-do-rompimento', 'Maça do Rompimento', 'Armas mágicas', 'raro', 'sim', 'Contra corruptores e mortos-vivos, causa 2d6 de dano radiante adicional; alvo com até 25 PV após o dano faz resistência de Sabedoria CD 15 ou é destruído, e em caso de sucesso fica amedrontado até o fim do próximo turno. Emite luz.'),
  ('maca-do-terror', 'Maça do Terror', 'Armas mágicas', 'raro', 'sim', 'Tem 3 cargas. Pode gastar uma ação e carga para que criaturas escolhidas a até 9 m façam resistência de Sabedoria CD 15 ou fiquem amedrontadas por 1 minuto. Recupera 1d3 cargas ao amanhecer.'),
  ('machado-furioso', 'Machado Furioso', 'Armas mágicas', 'raro', 'sim', 'Machado mágico +1 que aumenta o máximo de PV em 1 por nível. Maldição: o usuário reluta em se separar dele, tem desvantagem com outras armas e pode entrar em frenesi ao sofrer dano de criatura hostil (Sabedoria CD 15 evita).'),
  ('malha-do-efreeti', 'Malha do Efreeti', 'Armaduras mágicas', 'lendário', 'sim', 'Cota de malha +3 que concede imunidade a fogo e permite compreender e falar Primordial, além de permanecer e atravessar rocha derretida como terreno sólido.'),
  ('malha-elfica', 'Malha Élfica', 'Armaduras mágicas', 'raro', NULL, 'Camisa de malha +1. Quem a veste é considerado proficiente com ela mesmo sem proficiência em armaduras médias.'),
  ('manoplas-de-forca-do-ogro', 'Manoplas de Força do Ogro', 'Itens maravilhosos', 'incomum', 'sim', 'Define Força como 19 enquanto usadas; não têm efeito se o valor já for 19 ou maior.'),
  ('manto-da-aranha', 'Manto da Aranha', 'Itens maravilhosos', 'muito raro', 'sim', 'Concede resistência a veneno, escalada igual ao deslocamento de caminhada, movimento em superfícies e tetos com mãos livres, passagem por teias e imunidade a ficar preso nelas. Uma vez por dia, permite conjurar teia (CD 13) com área dobrada.'),
  ('manto-da-arraia', 'Manto da Arraia', 'Itens maravilhosos', 'incomum', NULL, 'Com o capuz sobre a cabeça, permite respirar debaixo d’água e concede deslocamento de natação de 12 m; colocar ou retirar o capuz requer uma ação.'),
  ('manto-de-carisma', 'Manto de Carisma', 'Itens maravilhosos', 'raro', 'sim', 'Define Carisma como 19 enquanto usado; não tem efeito se o valor já for 19 ou maior.'),
  ('manto-de-deslocamento', 'Manto de Deslocamento', 'Itens maravilhosos', 'raro', 'sim', 'Cria uma ilusão que impõe desvantagem aos ataques contra você. O efeito é suprimido até o início do próximo turno quando você sofre dano e enquanto estiver incapacitado, impedido ou sem poder se mover.'),
  ('manto-de-invisibilidade', 'Manto de Invisibilidade', 'Itens maravilhosos', 'lendário', 'sim', 'Cobrir a cabeça com o capuz torna você e o que veste ou carrega invisíveis. Tem duração total de 2 horas; recupera 1 hora para cada 12 horas sem uso.'),
  ('manto-de-protecao', 'Manto de Proteção', 'Itens maravilhosos', 'incomum', 'sim', 'Concede +1 na CA e nos testes de resistência enquanto usado.'),
  ('manto-de-resistencia-a-magia', 'Manto de Resistência à Magia', 'Itens maravilhosos', 'raro', 'sim', 'Concede vantagem em testes de resistência contra magias enquanto vestido.'),
  ('manto-do-morcego', 'Manto do Morcego', 'Itens maravilhosos', 'raro', 'sim', 'Concede vantagem em Furtividade. Em penumbra ou escuridão, permite voar a 12 m enquanto segura suas bordas. Uma vez por dia, também permite conjurar metamorfose sobre si para virar morcego.'),
  ('manto-elfico', 'Manto Élfico', 'Itens maravilhosos', 'incomum', 'sim', 'Com o capuz, impõe desvantagem a Percepção para vê-lo e concede vantagem em Furtividade para se esconder; a cor se adapta para camuflagem.'),
  ('manual-de-rapidez-de-movimentos', 'Manual de Rapidez de Movimentos', 'Itens maravilhosos', 'muito raro', NULL, 'Após 48 horas de estudo e prática em até 6 dias, aumenta Destreza em 2, até o máximo permitido. Perde a magia e a recupera após um século.'),
  ('manual-de-saude-corporal', 'Manual de Saúde Corporal', 'Itens maravilhosos', 'muito raro', NULL, 'Após 48 horas de estudo e prática em até 6 dias, aumenta Constituição em 2, até o máximo permitido. Perde a magia e a recupera após um século.'),
  ('manual-do-bom-exercicio', 'Manual do Bom Exercício', 'Itens maravilhosos', 'muito raro', NULL, 'Após 48 horas de estudo e prática em até 6 dias, aumenta Força em 2, até o máximo permitido. Perde a magia e a recupera após um século.'),
  ('manual-dos-golens', 'Manual dos Golens', 'Itens maravilhosos', 'muito raro', NULL, 'Manual mágico para construir um tipo específico de golem. Exige ser conjurador com pelo menos dois espaços de magia de 5º nível e requer tempo e suprimentos conforme o tipo de golem; ao concluir, o manual é consumido e o golem fica sob seu controle. Os custos listados são de fabricação, não preço do manual.'),
  ('marca-congelante', 'Marca Congelante', 'Armas mágicas', 'muito raro', 'sim', 'Espada que causa 1d6 de dano de frio adicional e concede resistência a fogo enquanto empunhada. Em frio intenso emite luz; ao sacá-la, pode extinguir chamas não mágicas próximas uma vez por hora.'),
  ('martelo-dos-trovoes', 'Martelo dos Trovões', 'Armas mágicas', 'lendário', NULL, 'Malho mágico +1 com 5 cargas. Sua propriedade Destruidor de Gigantes requer sintonização enquanto se usa cinturão de força de gigante e manoplas de força do ogro: aumenta Força em 4 (máximo 30) e pode matar um gigante com um 20 natural (Constituição CD 17). Gastando carga, o arremesso causa trovão e pode atordoar criaturas próximas (CD 17); recupera 1d4 + 1 cargas ao amanhecer.'),
  ('matadora-de-dragoes', 'Matadora de Dragões', 'Armas mágicas', 'raro', NULL, 'Espada mágica +1 que causa 3d6 de dano adicional do tipo da arma ao atingir qualquer criatura do tipo dragão, incluindo tartarugas-dragão e wyverns.')
) AS items(id, name, subcategory, rarity, attunement, description)
ON CONFLICT (id) DO NOTHING;

COMMIT;
